#[cfg(test)]
mod tests {
    use super::*;

    fn two_hard() -> StreamScan {
        StreamScan {
            findings: vec![
                StreamFinding::hard("two-hard", "injection", "one", 0),
                StreamFinding::hard("two-hard", "toxicity", "two", 1),
            ],
        }
    }

    #[test]
    fn two_distinct_hard_findings_return_both_categories() {
        let decision = refuse_after_collect(&two_hard());
        assert_eq!(decision.refused, true);
        assert_eq!(decision.categories.len(), 2);
        assert_eq!(decision.categories.contains(&"injection".to_string()), true);
        assert_eq!(decision.categories.contains(&"toxicity".to_string()), true);
        assert_eq!(decision.ledger_findings.len() >= 2, true);
    }

    #[test]
    fn empty_scan_does_not_refuse() {
        let decision = refuse_after_collect(&StreamScan::default());
        assert_eq!(decision.refused, false);
        assert_eq!(decision.categories.is_empty(), true);
        assert_eq!(decision.ledger_findings.is_empty(), true);
    }

    #[test]
    fn collect_does_not_drop_the_second_hard_row() {
        let hard = collect_hard_findings(&two_hard());
        assert_eq!(hard.len(), 2);
        assert_eq!(hard[0].category, "injection");
        assert_eq!(hard[1].category, "toxicity");
    }
}
